targets.expr:
histogram_quantile(
  0.95,
  sum by (le) (
    rate(
      http_server_requests_seconds_bucket{
        application="api-gateway"
      }[$__rate_interval]
    )
  )
)

sum(
  rate(
    jvm_gc_pause_seconds_sum{
      application="request-service"
    }[5m]
  )
)
/
clamp_min(
  sum(
    rate(
      jvm_gc_pause_seconds_count{
        application="request-service"
      }[5m]
    )
  ),
  0.000001
)

sum(
  rate(
    hlrms_requests_completed_total{
      application="request-worker"
    }[5m]
  )
) or vector(0)

sum(
  rate(
    rabbitmq_detailed_queue_messages_delivered_ack_total{
      queue="hlrms.request.processing.queue"
    }[5m]
  )
)
+
sum(
  rate(
    rabbitmq_detailed_queue_messages_delivered_total{
      queue="hlrms.request.processing.queue"
    }[5m]
  )
)
